//! The eight Duckpools lending pools on mainnet, as deployed.
//!
//! Identities come from `duckpools/off-chain-bot/consts.py` (CC0) and the
//! pool scripts from the unspent pool boxes captured on 2026-09-05, which
//! are the fixtures under `test/fixtures`. A pool NFT was minted with more
//! than one unit (the deployer's token bag holds the rest), so the script
//! is what identifies the pool box, and the NFT confirms it.

/// One lending pool.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Pool {
    /// Short stable key: `erg`, `sigusd`, …
    pub key: &'static str,
    /// The pooled asset's ticker as users know it.
    pub ticker: &'static str,
    /// Decimals of the pooled asset (and of its lend token).
    pub decimals: u8,
    pub pool_nft: &'static str,
    pub lend_token: &'static str,
    pub borrow_token: &'static str,
    /// The pooled token's id; `None` for the ERG pool, whose asset is the
    /// box value itself.
    pub currency_id: Option<&'static str>,
    /// The pool contract, hex.
    pub ergo_tree: &'static str,
}

impl Pool {
    pub fn is_erg(&self) -> bool {
        self.currency_id.is_none()
    }
}

